CREATE DATABASE IF NOT EXISTS student_management;
USE student_management;
CREATE TABLE departments(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL UNIQUE);
CREATE TABLE users(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,email VARCHAR(150) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,role ENUM('admin','faculty','student') NOT NULL DEFAULT 'student',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE courses(id INT AUTO_INCREMENT PRIMARY KEY,code VARCHAR(20) NOT NULL UNIQUE,name VARCHAR(120) NOT NULL,credits INT NOT NULL DEFAULT 3,department_id INT,FOREIGN KEY(department_id) REFERENCES departments(id) ON DELETE SET NULL);
CREATE TABLE students(id INT AUTO_INCREMENT PRIMARY KEY,student_number VARCHAR(30) NOT NULL UNIQUE,name VARCHAR(100) NOT NULL,email VARCHAR(150) NOT NULL UNIQUE,phone VARCHAR(20),date_of_birth DATE,gender VARCHAR(20),department_id INT,course_id INT,year_of_study INT NOT NULL DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(department_id) REFERENCES departments(id) ON DELETE SET NULL,FOREIGN KEY(course_id) REFERENCES courses(id) ON DELETE SET NULL);
CREATE TABLE faculty(id INT AUTO_INCREMENT PRIMARY KEY,employee_number VARCHAR(30) NOT NULL UNIQUE,name VARCHAR(100) NOT NULL,email VARCHAR(150) NOT NULL UNIQUE,department_id INT,FOREIGN KEY(department_id) REFERENCES departments(id) ON DELETE SET NULL);
CREATE TABLE attendance(id INT AUTO_INCREMENT PRIMARY KEY,student_id INT NOT NULL,course_id INT NOT NULL,attendance_date DATE NOT NULL,status ENUM('Present','Absent') NOT NULL,UNIQUE(student_id,course_id,attendance_date),FOREIGN KEY(student_id) REFERENCES students(id) ON DELETE CASCADE,FOREIGN KEY(course_id) REFERENCES courses(id) ON DELETE CASCADE);
CREATE TABLE grades(id INT AUTO_INCREMENT PRIMARY KEY,student_id INT NOT NULL,course_id INT NOT NULL,exam_type VARCHAR(50) NOT NULL,marks DECIMAL(5,2) NOT NULL,max_marks DECIMAL(5,2) NOT NULL DEFAULT 100,FOREIGN KEY(student_id) REFERENCES students(id) ON DELETE CASCADE,FOREIGN KEY(course_id) REFERENCES courses(id) ON DELETE CASCADE);
